const cards=values=>`<div class="trade-grid">${values.map(([title,value,hint])=>`<div class="trade-card"><span class="muted">${title}</span><strong>${value}</strong>${hint?`<p class="muted">${hint}</p>`:''}</div>`).join('')}</div>`;
async function api(path,method='GET',value,signal){
 const request=async(url,options)=>{try{return await fetch(url,options);}catch(error){if(error.name==='AbortError')throw error;throw Error(method==='GET'?'Не вдалося з’єднатися із сервером. Перевірте підключення й повторіть.':'З’єднання перервано. Оновіть список, щоб перевірити результат операції.');}};
 if(!csrf){await tradingReady();csrf=(await window.TradeDirectories.bootstrap()).csrf;}
 const r=await request('/api/erp/'+path,{method,signal,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:value===undefined?undefined:JSON.stringify(value)});
 if(r.status===401){location.href='/';throw Error('Сеанс завершився.');}
 let result;try{result=await r.json();}catch{throw Error('Сервер не відповідає. Повторіть спробу.');}
 if(!r.ok)throw Object.assign(Error(result.error||'Не вдалося виконати дію.'),{status:r.status,code:result.code,detail:result});if(method==='GET')await window.TradeDirectories.hydrateCaptions(result);return result;
}
