let dialog=null,restoreFocus=null;
function markDirty(d=dialog){if(d?.open)d.dataset.dirty='1';}
function dialogStatus(d,text){const status=d?.querySelector('#tradeFormStatus');if(status)status.textContent=text;}
function busyDialog(d,text='Збереження…'){
 if(!d?.open||d.dataset.busy==='1')return null;
 const disabled=[...d.querySelectorAll('button,input,select,textarea')].map(control=>[control,control.disabled]);
 d.dataset.busy='1';d.setAttribute('aria-busy','true');disabled.forEach(([control])=>control.disabled=true);dialogStatus(d,text);
 return()=>{delete d.dataset.busy;d.removeAttribute('aria-busy');disabled.forEach(([control,value])=>{if(control.isConnected)control.disabled=value;});dialogStatus(d,'');};
}
