 d.innerHTML=`<div class="trade-dialog-head"><h2 id="tradeDialogTitle">${esc(title)}</h2>${button('Закрити','close','aria-label="Закрити вікно"')}</div><div class="trade-dialog-body">${html}<p id="tradeFormError" class="trade-error" role="alert" tabindex="-1"></p><p id="tradeFormStatus" class="trade-saving" role="status" aria-live="polite"></p></div>${foot?`<div class="trade-dialog-foot">${foot}</div>`:''}`;
 document.body.append(d);d.addEventListener('input',()=>markDirty(d));d.addEventListener('change',()=>markDirty(d));
